n// --- HEADER JADWAL PRODUKSI ---\nmodel ProductionRelease {\n  Id            String   @id @default(uuid())\n  ReleaseNumber String   @unique\n  PlanDate      DateTime\n\n  Status ProductionStatus @default(DRAFT)\n  Notes  String?\n\n  // Rekap total agar UI dashboard lebih ringan (tidak perlu sum dari child)\n  TotalTargetQty Int @default(0)\n  TotalGoodQty   Int @default(0)\n  TotalNgQty     Int @default(0)\n\n  CreatedAt DateTime @default(now())\n  CreatedBy String\n  UpdatedAt DateTime @updatedAt\n\n  IsNoAttachment Boolean @default(false)\n\n  // 1 Jadwal rilis BANYAK PO (Forecast)\n  Forecasts   Forecast[]\n  LabelDatas  LabelData[]\n  Attachments ProductionReleaseAttachment[]\n\n  @@index([PlanDate])\n  @@index([Status])\n}\n\nmodel ProductionReleaseAttachment {\n  id Int @id @default(autoincrement())\n\n  FileName         String?\n  FilePath         String?\n  OriginalFileName String?\n  FileSize         Int?\n  MimeType         String?\n\n  CreatedAt DateTime @default(now())\n  CreatedBy String?\n  UpdatedAt DateTime @updatedAt\n  UpdatedBy String?\n\n  ProductionRelease   ProductionRelease? @relation(fields: [ProductionReleaseId], references: [Id])\n  ProductionReleaseId String?\n\n  @@index([ProductionReleaseId])\n  @@map(\"DeliveryAttachment\")\n}\n\nmodel Shopping {\n  Id          String       @id\n  Description String?\n  Type        TypeShopping\n  CreatedAt   DateTime     @default(now())\n  UpdatedAt   DateTime     @updatedAt\n  ForecastId  String?\n  CreatedBy   String\n  QtyPick     Int\n  MaterialId  String\n\n  ForecastData Forecast? @relation(fields: [ForecastId], references: [PoId], onDelete: Cascade)\n  MaterialData Material  @relation(fields: [MaterialId], references: [PartNumber])\n\n  @@index([ForecastId], map: \"Shopping_forecastId_fkey\")\n  @@index([MaterialId], map: \"Shopping_materialId_fkey\")\n}\n\nmodel ProductionReport {\n  Id              Int       @id @default(autoincrement())\n  Date            String?\n  Time            String?\n  ProductionStamp DateTime\n  NgQty           Int       @default(0)\n  StartTime       String?\n  StartStamp      DateTime?\n  EndTime         String?\n  EndStamp        DateTime?\n  StopMinute      Int?      @default(0)\n  LatchDate       String?\n  CableHDate      String?\n  CableLDate      String?\n  CoverDate       String?\n  RodDate         String?\n  SponsDate       String?\n  SponsRearDate   String?\n  ClipDate        String?\n  LeverDate       String?\n  SmallPadDate    String?\n  ActuatorDate    String?\n  BackPlateDate   String?\n  StampDate       String?\n  PoNumber        String?\n  CreatedAt       DateTime  @default(now())\n  UpdatedAt       DateTime  @updatedAt\n  ValidatedAt     DateTime?\n  ValidatedBy     String?\n  RecordType      PartType?\n  Qty             Int       @default(0)\n  ManPowerUid     String\n  FinishGoodId    String\n  ForecastId      String?\n\n  ManPowerData ManPower   @relation(fields: [ManPowerUid], references: [Uid])\n  FGData       FinishGood @relation(fields: [FinishGoodId], references: [PartNumber])\n  ForecastData Forecast?  @relation(fields: [ForecastId], references: [PoId])\n\n  @@unique([Date, ManPowerUid, FinishGoodId, CreatedAt])\n  @@index([ForecastId])\n}\n\nmodel LabelData {\n  Id           Int     @id @default(autoincrement())\n  LabelNumber  String  @unique\n  FinishGoodId String\n  ForecastId   String //Ambil dari POID\n  Scanned      Boolean @default(false)\n  QtyThisBox   Int     @default(0)\n\n  DeliveryHistory       DeliveryHistory?\n  PokayokeHistory       PokayokeScanHistory[]\n  PartData              FinishGood            @relation(fields: [FinishGoodId], references: [PartNumber])\n  POData                Forecast              @relation(fields: [ForecastId], references: [PoId], onDelete: Cascade)\n  ProductionRelease     ProductionRelease?    @relation(fields: [ProductionReleaseId], references: [Id])\n  ProductionReleaseId   String?\n  PokayokeScanHistoryId String?\n\n  @@index([FinishGoodId], map: \"LabelData_finishGoodId_fkey\")\n  @@index([ForecastId], map: \"LabelData_forecastId_fkey\")\n  @@index([ProductionReleaseId])\n}\n\nmodel PokayokeScanHistory {\n  Id          Int                   @id @default(autoincrement())\n  LabelNumber String\n  PoId        String //Forecast.PoId\n  PartNumber  String\n  PartName    String\n  CreatedAt   DateTime              @default(now())\n  CreatedBy   String\n  Status      PokayokeCompareStatus\n\n  LabelData   LabelData? @relation(fields: [LabelDataId], references: [Id])\n  LabelDataId Int?\n}\n\nmodel DeliveryHistory {\n  Id          Int      @id @default(autoincrement())\n  ForecastId  String //ambil dari PoID\n  Qty         Int\n  CreatedAt   DateTime @default(now())\n  CreatedBy   String\n  LabelDataId String   @unique(map: \"DeliveryHistory_pk\")\n\n  PoData    Forecast  @relation(fields: [ForecastId], references: [PoId])\n  LabelData LabelData @relation(fields: [LabelDataId], references: [LabelNumber])\n\n  @@index([ForecastId], map: \"DeliveryHistory_forecastId_fkey\")\n  @@index([CreatedAt])\n}\n\n// --- SYSTEM SETTINGS ---\n\nmodel LineStatus {\n  Id           Int    @id @default(autoincrement())\n  LineName     String\n  FinishGoodId String\n\n  CurrentProduction FinishGood @relation(fields: [FinishGoodId], references: [PartNumber])\n\n  @@index([FinishGoodId], map: \"LineStatus_finishGoodId_fkey\")\n}\n\nmodel EmailNotification {\n  Id    Int              @id @default(autoincrement())\n  Name  String\n  Email String\n  Type  NotificationType @default(DEFAULT)\n}\n\nmodel DashboardSetting {\n  Id        Int      @id @default(autoincrement())\n  StartDate DateTime\n  EndDate   DateTime\n  UpdatedAt DateTime\n}\n\n// --- AUDIT LOG ---\n\nmodel LogProcess {\n  ProcessId         String             @id @db.VarChar(50)\n  FunctionId        String             @db.VarChar(50)\n  FunctionName      String             @db.VarChar(255)\n  ProcessStatus     String             @db.VarChar(20)\n  ProcessStart      DateTime\n  ProcessEnd        DateTime?\n  ProcessDate       DateTime\n  CreatedAt         DateTime\n  CreatedBy         String?\n  LogProcessDetails LogProcessDetail[]\n\n  @@index([ProcessId])\n  @@index([FunctionId])\n  @@index([ProcessDate])\n  @@index([ProcessStatus])\n}\n\nmodel LogProcessDetail {\n  ProcessDetailId BigInt      @id @default(autoincrement())\n  ProcessId       String      @db.VarChar(50)\n  MessageId       String      @db.VarChar(50)\n  Message         String      @db.Text\n  Type            String      @db.VarChar(20)\n  Location        String      @db.VarChar(255)\n  ProcessDate     DateTime\n  CreatedAt       DateTime\n  LogProcess      LogProcess? @relation(fields: [ProcessId], references: [ProcessId], onDelete: Cascade, onUpdate: Cascade)\n\n  @@index([ProcessId])\n  @@index([MessageId])\n  @@index([Type])\n  @@index([ProcessDate])\n}\n\nmodel MTCUserSession {\n  SessionId String   @id @default(uuid())\n  UserId    String\n  UserAgent String\n  IpAddress String\n  IsActive  Boolean  @default(true)\n  CreatedAt DateTime @default(now())\n  ExpiresAt DateTime\n}\n\nmodel MTCUserManagement {\n  Id          String    @id @default(uuid())\n  UserId      String    @unique\n  PhoneNumber String?   @db.VarChar(32)\n  IsActive    Boolean   @default(true)\n  Name        String\n  LastLogin   DateTime?\n  Email       String    @unique\n\n  SsoObjectId String @unique\n\n  RoleId      Int?\n  Role        MTCRole?     @relation(fields: [RoleId], references: [Id], onUpdate: Cascade)\n  mtcauthLogs MTCAuthLog[]\n  ApiKeys     ApiKey[]\n\n  @@index([Email])\n  @@index([SsoObjectId])\n}\n\nenum MTCAuthAction {\n  LOGIN\n  LOGOUT\n  SSO_CALLBACK\n}\n\nenum MTCAuthStatus {\n  SUCCESS\n  FAILED\n}\n\nmodel MTCAuthLog {\n  Id            String        @id @default(uuid())\n  UserId        String?\n  EmailAttempt  String?       @db.VarChar(255)\n  Action        MTCAuthAction\n  Status        MTCAuthStatus\n  FailureReason String?       @db.VarChar(255)\n  IpAddress     String?